  let steps = [], stepIndex = 0, running = false, speed = 1, width = 1, height = 1, dpr = 1, lastTick = 0, palette = {};
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const nums = (v, limit = 40) => String(v).split(/[\s,，;；]+/).filter(Boolean).map(Number).filter(Number.isFinite).slice(0, limit);
  const groups = (v, size, limit = 40) => nums(v, limit * size).reduce((out, n, i) => { if (i % size === 0) out.push([]); out.at(-1).push(n); return out; }, []).filter((g) => g.length === size);
  const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
  const key = (a, b) => `${a}-${b}`;
  const undirected = (a, b) => [a, b].sort().join('-');
  function push(label, kind, data, metrics = [0, 0, '--'], note = '') { steps.push({ label, kind, metrics, note, ...clone(data) }); }
  function must(condition, message) { if (!condition) throw new Error(message); }

  function setUpPage() {
    document.body.className = cfg.theme || '';
    document.title = `${cfg.title} · Algorithm Lab`;
    $('title').textContent = cfg.title; $('monogram').textContent = cfg.mono; $('eyebrow').textContent = cfg.eye;
    $('primary-label').textContent = cfg.aLabel; $('input-a').value = cfg.a;
    $('secondary-wrap').hidden = !cfg.bLabel;
    if (cfg.bLabel) { $('secondary-label').textContent = cfg.bLabel; $('input-b').value = cfg.b; }
    $('option-wrap').hidden = true;
    cfg.metrics.forEach((label, i) => { $(`metric-label-${i + 1}`).textContent = label; });
    $('principle').textContent = cfg.principle; $('complexity').textContent = cfg.complexity;
    canvas.setAttribute('aria-label', `${cfg.title}执行过程动画`);
  }

  function defaultNodes(labels) {
    return labels.map((label, i) => ({ id:String(label), label:String(label), x:.5 + Math.cos(-Math.PI / 2 + i * Math.PI * 2 / labels.length) * .36, y:.5 + Math.sin(-Math.PI / 2 + i * Math.PI * 2 / labels.length) * .34 }));
  }

  function treePositions(root) {
    const out = [], levels = [], queue = root ? [[root, 0]] : [];
    while (queue.length) { const [node, depth] = queue.shift(); (levels[depth] ||= []).push(node); if (node.left) queue.push([node.left, depth + 1]); if (node.right) queue.push([node.right, depth + 1]); }
    levels.forEach((nodes, depth) => nodes.forEach((node, i) => out.push({ id:String(node.id), label:String(node.key ?? node.label ?? node.id), sub:node.priority == null ? '' : `p${node.priority}`, x:(i + 1) / (nodes.length + 1), y:.15 + depth * Math.min(.2, .66 / Math.max(1, levels.length - 1)), left:node.left ? String(node.left.id) : null, right:node.right ? String(node.right.id) : null })));
    return out;
  }

  function buildBucketSort() {
    const values = nums($('input-a').value).map(Number).filter((n) => n >= 0 && n <= 1).slice(0, 18);
    const count = clamp(Math.round(Number($('input-b').value) || 5), 2, 10);
    must(values.length >= 2, '请输入至少两个 0-1 之间的小数');
    const buckets = Array.from({ length: count }, () => []); let writes = 0;
    push('创建空桶', 'buckets', { values, buckets, activeValue:-1, activeBucket:-1, output:[] }, [0, count, 0], `${count} BUCKETS`);
    values.forEach((value, i) => { const b = Math.min(count - 1, Math.floor(value * count)); buckets[b].push(value); push(`把 ${value} 放入桶 ${b}`, 'buckets', { values, buckets, activeValue:i, activeBucket:b, output:[] }, [i + 1, b, 0], `FLOOR(${value} × ${count}) = ${b}`); });
    buckets.forEach((bucket, b) => { for (let i = 1; i < bucket.length; i++) { const hold = bucket[i]; let j = i - 1; while (j >= 0 && bucket[j] > hold) { bucket[j + 1] = bucket[j]; j--; } bucket[j + 1] = hold; push(`桶 ${b} 内部插入排序`, 'buckets', { values, buckets, activeValue:-1, activeBucket:b, output:[] }, [values.length, b, writes], 'INSERTION SORT INSIDE BUCKET'); } });
    const output = []; buckets.forEach((bucket, b) => bucket.forEach((value) => { output.push(value); writes++; push(`依次合并桶 ${b}`, 'buckets', { values, buckets, activeValue:-1, activeBucket:b, output }, [values.length, b, writes], `OUTPUT ${value}`); }));
  }

  function buildQuickselect() {
    const values = nums($('input-a').value).map(Math.round).slice(0, 22); must(values.length >= 2, '请输入至少两个整数');
    const target = clamp(Math.round(Number($('input-b').value) || 1) - 1, 0, values.length - 1); let left = 0, right = values.length - 1, partitions = 0, comparisons = 0;
    push(`目标索引 ${target}`, 'array', { values, range:[left, right], pointers:{ k:target }, active:[] }, [0, 0, '--'], `SELECT RANK ${target + 1}`);
    while (left <= right) {
      const pivot = values[right]; let store = left; partitions++;
      for (let i = left; i < right; i++) { comparisons++; push(`比较 ${values[i]} 与基准 ${pivot}`, 'array', { values, range:[left, right], pointers:{ i, p:right, k:target, s:store }, active:[i, right] }, [partitions, comparisons, '--'], values[i] <= pivot ? 'MOVE TO LEFT PARTITION' : 'KEEP ON RIGHT'); if (values[i] <= pivot) { [values[i], values[store]] = [values[store], values[i]]; store++; } }
      [values[store], values[right]] = [values[right], values[store]];
      push(`基准落在索引 ${store}`, 'array', { values, range:[left, right], pointers:{ p:store, k:target }, active:[store], selected:[store] }, [partitions, comparisons, store === target ? values[store] : '--'], 'PARTITION COMPLETE');
      if (store === target) return; if (store < target) left = store + 1; else right = store - 1;
    }
  }

  function buildTwoPointers() {
    const values = nums($('input-a').value).map(Math.round).sort((a,b) => a-b).slice(0, 28); const target = Math.round(Number($('input-b').value)); must(values.length >= 2 && Number.isFinite(target), '请输入整数数组和目标和');
    let left = 0, right = values.length - 1;
    while (left < right) { const sum = values[left] + values[right]; push(sum === target ? `找到数对 ${values[left]} + ${values[right]} = ${sum}` : `${values[left]} + ${values[right]} = ${sum}`, 'array', { values, range:[left,right], pointers:{ L:left, R:right }, active:[left,right], selected:sum === target ? [left,right] : [] }, [left, right, sum], sum === target ? 'PAIR FOUND' : sum < target ? 'SUM TOO SMALL · MOVE LEFT' : 'SUM TOO LARGE · MOVE RIGHT'); if (sum === target) return; if (sum < target) left++; else right--; }
    push('没有找到目标数对', 'array', { values, active:[], pointers:{ L:left, R:right } }, [left, right, '--'], 'NO PAIR');
  }

  function buildSlidingWindow() {
    const values = nums($('input-a').value).map(Math.round).slice(0, 30); const k = clamp(Math.round(Number($('input-b').value) || 3), 1, values.length); must(values.length, '请输入整数数组');
    let sum = values.slice(0, k).reduce((a,b) => a+b, 0), best = sum, bestRange = [0, k - 1];
    push(`初始化长度 ${k} 的窗口`, 'array', { values, range:[0,k-1], selected:bestRange }, [0, sum, best], 'INITIAL WINDOW');
    for (let start = 1; start + k <= values.length; start++) { sum += values[start + k - 1] - values[start - 1]; if (sum > best) { best = sum; bestRange = [start,start+k-1]; } push(`窗口滑到 [${start}, ${start+k-1}]`, 'array', { values, range:[start,start+k-1], active:[start-1,start+k-1], selected:Array.from({length:bestRange[1]-bestRange[0]+1},(_,i)=>bestRange[0]+i) }, [start, sum, best], `-${values[start-1]} +${values[start+k-1]}`); }
  }

  function buildBoyerMoore() {
    const text = $('input-a').value, pattern = $('input-b').value; must(pattern.length && text.length >= pattern.length, '模式串不能为空且不能长于文本');
    const bad = {}; [...pattern].forEach((ch,i) => bad[ch] = i); let start = 0, comparisons = 0;
    while (start <= text.length - pattern.length) { let j = pattern.length - 1; while (j >= 0) { comparisons++; const match = pattern[j] === text[start + j]; push(match ? `字符 ${pattern[j]} 匹配` : `坏字符 ${text[start+j]} 失配`, 'text', { rows:[{label:'TEXT',cells:[...text],active:[start+j],range:[start,start+pattern.length-1]},{label:'PATTERN',cells:Array(start).fill('·').concat([...pattern]),active:[start+j]}] }, [start, comparisons, 0], match ? 'COMPARE RIGHT TO LEFT' : 'BAD CHARACTER'); if (!match) break; j--; }
      if (j < 0) { push(`在索引 ${start} 找到匹配`, 'text', { rows:[{label:'TEXT',cells:[...text],selected:Array.from({length:pattern.length},(_,i)=>start+i)},{label:'PATTERN',cells:Array(start).fill('·').concat([...pattern]),selected:Array.from({length:pattern.length},(_,i)=>start+i)}] }, [start, comparisons, 0], 'MATCH FOUND'); return; }
      const shift = Math.max(1, j - (bad[text[start + j]] ?? -1)); push(`模式串向右跳 ${shift} 位`, 'text', { rows:[{label:'TEXT',cells:[...text],active:[start+j],range:[start,start+pattern.length-1]},{label:'PATTERN',cells:Array(start).fill('·').concat([...pattern])}] }, [start, comparisons, shift], `SHIFT = MAX(1, ${j} - LAST[${text[start+j]}])`); start += shift;
    }
    push('文本中不存在模式串', 'text', { rows:[{label:'TEXT',cells:[...text]}] }, [start, comparisons, '--'], 'NO MATCH');
  }

  function buildZ() {
    const text = $('input-a').value.trim().slice(0, 40); must(text.length >= 2, '请输入至少两个字符'); const z = Array(text.length).fill(0); let left = 0, right = 0;
    for (let i = 1; i < text.length; i++) { if (i <= right) z[i] = Math.min(right - i + 1, z[i-left]); push(`处理索引 ${i}`, 'text', { rows:[{label:'STRING',cells:[...text],active:[i],range:right>=left?[left,right]:null},{label:'Z',cells:z.map(String),active:[i]}] }, [i, `${left}-${right}`, z[i]], i <= right ? 'REUSE MIRROR VALUE' : 'START NEW MATCH'); while (i + z[i] < text.length && text[z[i]] === text[i + z[i]]) { z[i]++; if (i + z[i] - 1 > right) { left = i; right = i + z[i] - 1; } push(`扩展 Z[${i}] 到 ${z[i]}`, 'text', { rows:[{label:'STRING',cells:[...text],active:[i+z[i]-1],range:[left,right]},{label:'Z',cells:z.map(String),active:[i]}] }, [i, `${left}-${right}`, z[i]], 'PREFIX EXTENDED'); } }
    z[0] = text.length; push('Z 数组计算完成', 'text', { rows:[{label:'STRING',cells:[...text]},{label:'Z',cells:z.map(String),selected:z.map((_,i)=>i)}] }, [text.length, `${left}-${right}`, Math.max(...z.slice(1))], 'Z ARRAY COMPLETE');
  }

  function buildManacher() {
    const source = $('input-a').value.trim().slice(0, 30); must(source.length, '请输入字符串'); const chars = ['^','#',...[...source].flatMap((c)=>[c,'#']),'$'], p = Array(chars.length).fill(0); let center = 0, right = 0, best = 0;
    for (let i = 1; i < chars.length - 1; i++) { const mirror = 2 * center - i; if (i < right) p[i] = Math.min(right-i, p[mirror] || 0); while (chars[i+1+p[i]] === chars[i-1-p[i]]) { p[i]++; best = Math.max(best,p[i]); push(`以 ${i} 为中心扩展`, 'text', { rows:[{label:'TRANSFORM',cells:chars,active:[i-p[i],i+p[i]],range:[i-p[i],i+p[i]]},{label:'RADIUS',cells:p.map(String),active:[i]}] }, [i,right,best], `MIRROR ${mirror}`); } if (i+p[i] > right) { center=i; right=i+p[i]; } }
    const i = p.indexOf(best); push(`最长回文长度 ${best}`, 'text', { rows:[{label:'TRANSFORM',cells:chars,selected:Array.from({length:best*2+1},(_,k)=>i-best+k)},{label:'RADIUS',cells:p.map(String),active:[i]}] }, [i,right,best], 'LONGEST PALINDROME');
  }

  function buildSuffixArray() {
    const text = $('input-a').value.trim().slice(0, 18); must(text.length >= 2, '请输入至少两个字符'); let order = [...text].map((_,i)=>i), rank = [...text].map((c)=>c.charCodeAt(0)), round = 0;
    push('创建全部后缀', 'suffix', { text, order, ranks:rank, active:-1, lcp:[] }, [0, text.length, 0], 'INITIAL SUFFIXES');
    for (let k = 1; k < text.length; k *= 2) { order.sort((a,b)=>(rank[a]-rank[b])||((rank[a+k]??-1)-(rank[b+k]??-1))); const next=Array(text.length).fill(0); for(let i=1;i<order.length;i++) next[order[i]]=next[order[i-1]]+((rank[order[i-1]]!==rank[order[i]]||(rank[order[i-1]+k]??-1)!==(rank[order[i]+k]??-1))?1:0); rank=next; round++; push(`按前 ${k*2} 个字符排序`, 'suffix', { text, order, ranks:rank, active:-1, lcp:[] }, [round,text.length,0], `DOUBLING K=${k}`); if(rank[order.at(-1)]===text.length-1) break; }
    const lcp=Array(text.length).fill(0); let max=0; for(let i=1;i<order.length;i++){let n=0; while(text[order[i]+n]===text[order[i-1]+n]&&order[i]+n<text.length&&order[i-1]+n<text.length)n++; lcp[i]=n; max=Math.max(max,n); push(`比较相邻后缀，LCP=${n}`, 'suffix',{text,order,ranks:rank,active:i,lcp},[round,text.length,max],`${order[i-1]} ↔ ${order[i]}`);}
  }

  function eulerGraph() { return { nodes:defaultNodes(['A','B','C','D','E','F']), edges:[['A','B'],['B','C'],['C','A'],['A','D'],['D','E'],['E','F'],['F','D'],['D','B']].map(([a,b],i)=>({id:i,a,b})) }; }
  function buildEuler() {
    const g=eulerGraph(), start=String($('input-a').value||'A').toUpperCase(); must(g.nodes.some(n=>n.id===start),'起点必须是 A-F'); const adj={}; g.nodes.forEach(n=>adj[n.id]=[]); g.edges.forEach(e=>{adj[e.a].push([e.b,e.id]);adj[e.b].push([e.a,e.id]);}); const stack=[start], path=[], used=new Set();
    while(stack.length){const v=stack.at(-1), next=adj[v].find(([,id])=>!used.has(id)); if(next){used.add(next[1]);stack.push(next[0]);push(`沿边 ${v}-${next[0]} 前进`,'graph',{...g,activeNodes:[v,next[0]],activeEdges:[next[1]],selectedEdges:[...used],stack,path},[stack.length,used.size,path.length],'FOLLOW UNUSED EDGE');}else{path.push(stack.pop());push(`节点 ${v} 无未使用边，加入路径`,'graph',{...g,activeNodes:[v],selectedEdges:[...used],stack,path},[stack.length,used.size,path.length],'BACKTRACK TO EULER PATH');}}
  }

  function baseTreeGraph(weights) { const labels='ABCDEFGHI'.split(''); const parent=[-1,0,0,1,1,2,2,3,3]; const pos=[[.5,.1],[.3,.3],[.7,.3],[.18,.53],[.4,.53],[.6,.53],[.82,.53],[.1,.78],[.25,.78]]; return {nodes:labels.map((id,i)=>({id,label:weights?`${id}:${weights[i]}`:id,x:pos[i][0],y:pos[i][1]})),edges:parent.flatMap((p,i)=>p<0?[]:[{id:i,a:labels[p],b:labels[i]}]),parent:Object.fromEntries(labels.map((id,i)=>[id,parent[i]<0?null:labels[parent[i]]]))}; }
  function buildLca() {
    const [u0,v0]=String($('input-a').value).toUpperCase().split(/[\s,，]+/), g=baseTreeGraph(); must(g.parent[u0]!==undefined&&g.parent[v0]!==undefined,'节点必须为 A-I'); const path=(v)=>{const a=[];while(v){a.push(v);v=g.parent[v];}return a;}; const pu=path(u0),pv=path(v0); let u=u0,v=v0,moves=0; const depth=(x)=>path(x).length-1;
    while(depth(u)>depth(v)){push(`提升较深节点 ${u}`,'graph',{...g,activeNodes:[u],selectedNodes:[...pu.filter(x=>depth(x)>=depth(u))]},[moves,u,'--'],'ALIGN DEPTH');u=g.parent[u];moves++;} while(depth(v)>depth(u)){push(`提升较深节点 ${v}`,'graph',{...g,activeNodes:[v]},[moves,v,'--'],'ALIGN DEPTH');v=g.parent[v];moves++;} while(u!==v){push(`同步提升 ${u} 与 ${v}`,'graph',{...g,activeNodes:[u,v]},[moves,`${u}/${v}`,'--'],'BINARY LIFT');u=g.parent[u];v=g.parent[v];moves+=2;} push(`最近公共祖先是 ${u}`,'graph',{...g,activeNodes:[u],selectedNodes:[u]},[moves,u,u],'LCA FOUND');
  }

  function buildHungarian() {
    const matrix=String($('input-a').value).split(/[;；]+/).map(r=>nums(r,8));
    const n=matrix.length, rowLabels=Array.from({length:n},(_,i)=>`W${i+1}`), colLabels=Array.from({length:n},(_,i)=>`J${i+1}`);
    must(n>=2&&matrix.every(r=>r.length===n)&&n<=6,'请输入 2-6 阶方阵');
    const u=Array(n+1).fill(0),v=Array(n+1).fill(0),p=Array(n+1).fill(0),way=Array(n+1).fill(0);
    const reduced=()=>matrix.map((row,r)=>row.map((cost,c)=>cost-u[r+1]-v[c+1]));
    const matching=()=>Array.from({length:n},(_,j)=>p[j+1]?[p[j+1]-1,j]:null).filter(Boolean);
    for(let worker=1;worker<=n;worker++){
      p[0]=worker;
      let job0=0;
      const minv=Array(n+1).fill(Infinity),used=Array(n+1).fill(false);
      do{
        used[job0]=true;
        const worker0=p[job0];
        let delta=Infinity,job1=0;
        for(let job=1;job<=n;job++)if(!used[job]){
          const current=matrix[worker0-1][job-1]-u[worker0]-v[job];
          if(current<minv[job]){minv[job]=current;way[job]=job0;}
          if(minv[job]<delta){delta=minv[job];job1=job;}
        }
        for(let job=0;job<=n;job++)if(used[job]){u[p[job]]+=delta;v[job]-=delta;}else minv[job]-=delta;
        job0=job1;
        push(`更新势能并选择作业 J${job0}`,'matrix',{matrix:reduced(),active:[worker0-1,job0-1],selected:matching(),rowLabels,colLabels},['势能',matching().length,'--'],`DELTA ${delta}`);
      }while(p[job0]!==0);
      do{
        const previous=way[job0];
        p[job0]=p[previous];
        job0=previous;
      }while(job0!==0);
      const selected=matching();
      push(`完成第 ${worker} 条增广匹配`,'matrix',{matrix:reduced(),active:selected.at(-1),selected,rowLabels,colLabels},['增广',selected.length,'--'],'AUGMENT ZERO-COST MATCHING');
    }
    const selected=matching(),best=selected.reduce((sum,[r,c])=>sum+matrix[r][c],0);
    push(`最优指派成本为 ${best}`,'matrix',{matrix:reduced(),selected,rowLabels,colLabels},['完成',selected.length,best],'HUNGARIAN O(N³) COMPLETE');
  }

  function coloringGraph(){const nodes=defaultNodes(['A','B','C','D','E','F','G']);const pairs=[['A','B'],['A','C'],['B','C'],['B','D'],['C','E'],['D','E'],['D','F'],['E','G'],['F','G'],['C','F']];return{nodes,edges:pairs.map(([a,b],id)=>({id,a,b}))};}
  function buildColoring(){const colors=clamp(Math.round(Number($('input-a').value)||3),2,4),g=coloringGraph(),adj={};g.nodes.forEach(n=>adj[n.id]=[]);g.edges.forEach(e=>{adj[e.a].push(e.b);adj[e.b].push(e.a);});const assignment={},names=['青','金','绿','红'];let tries=0;function solve(i){if(i===g.nodes.length)return true;const v=g.nodes[i].id;for(let c=0;c<colors;c++){tries++;const conflict=adj[v].some(n=>assignment[n]===c);push(conflict?`${v} 不能使用颜色 ${c+1}`:`尝试给 ${v} 颜色 ${c+1}`,'graph',{...g,activeNodes:[v],nodeGroups:clone(assignment),trial:{node:v,group:c},groupNames:names},[v,tries,Object.keys(assignment).length],conflict?'NEIGHBOR CONFLICT':'PLACE COLOR');if(!conflict){assignment[v]=c;if(solve(i+1))return true;delete assignment[v];push(`撤销节点 ${v}`,'graph',{...g,activeNodes:[v],nodeGroups:clone(assignment),groupNames:names},[v,tries,Object.keys(assignment).length],'BACKTRACK');}}return false;}solve(0);push('图着色完成','graph',{...g,nodeGroups:assignment,selectedNodes:Object.keys(assignment),groupNames:names},['完成',tries,Object.keys(assignment).length],`${colors} COLORS`);}

  function buildCoinChange(){const coins=nums($('input-a').value).map(Math.round).filter(n=>n>0).slice(0,10),amount=clamp(Math.round(Number($('input-b').value)||10),1,60);must(coins.length,'请输入正整数硬币面额');const dp=Array(amount+1).fill(Infinity);dp[0]=0;for(let a=1;a<=amount;a++)for(const coin of coins)if(coin<=a&&dp[a-coin]+1<dp[a]){dp[a]=dp[a-coin]+1;push(`金额 ${a} 使用硬币 ${coin}`,'matrix',{matrix:[dp.map(v=>Number.isFinite(v)?v:'∞')],active:[0,a],selected:[[0,a-coin]],rowLabels:['MIN'],colLabels:Array.from({length:amount+1},(_,i)=>i)},[a,coin,Number.isFinite(dp[amount])?dp[amount]:'--'],`DP[${a}] = DP[${a-coin}] + 1`);}push(Number.isFinite(dp[amount])?`最少需要 ${dp[amount]} 枚硬币`:'目标金额不可达','matrix',{matrix:[dp.map(v=>Number.isFinite(v)?v:'∞')],active:[0,amount],selected:[[0,amount]],rowLabels:['MIN'],colLabels:Array.from({length:amount+1},(_,i)=>i)},[amount,'--',Number.isFinite(dp[amount])?dp[amount]:'∞'],'DP COMPLETE');}

  function buildKadane(){const values=nums($('input-a').value).map(Math.round).slice(0,30);must(values.length,'请输入整数数组');let current=values[0],best=values[0],start=0,bestRange=[0,0];push('从第一个元素开始','array',{values,range:[0,0],selected:[0]},[0,current,best],'INITIAL STATE');for(let i=1;i<values.length;i++){if(current+values[i]<values[i]){current=values[i];start=i;}else current+=values[i];if(current>best){best=current;bestRange=[start,i];}push(`处理索引 ${i}`,'array',{values,range:[start,i],active:[i],selected:Array.from({length:bestRange[1]-bestRange[0]+1},(_,k)=>bestRange[0]+k)},[i,current,best],current===values[i]?'RESTART HERE':'EXTEND CURRENT SUBARRAY');}}

  function buildMatrixChain(){const d=nums($('input-a').value).map(Math.round).filter(n=>n>0).slice(0,10),n=d.length-1;must(n>=2,'请输入至少三个正整数维度');const dp=Array.from({length:n},()=>Array(n).fill(0));for(let len=2;len<=n;len++)for(let i=0;i+len<=n;i++){const j=i+len-1;dp[i][j]=Infinity;for(let k=i;k<j;k++){const cost=dp[i][k]+dp[k+1][j]+d[i]*d[k+1]*d[j+1];if(cost<dp[i][j])dp[i][j]=cost;push(`区间 [${i+1},${j+1}] 在 ${k+1} 处分割`,'matrix',{matrix:dp.map(r=>r.map(v=>Number.isFinite(v)?v:'∞')),active:[i,j],selected:[[i,k],[k+1,j]],rowLabels:Array.from({length:n},(_,x)=>`A${x+1}`),colLabels:Array.from({length:n},(_,x)=>`A${x+1}`)},[len,`${i+1}-${j+1}`,dp[i][j]],`COST ${cost}`);}}}

  function tspGraph(n){const nodes=defaultNodes(Array.from({length:n},(_,i)=>String.fromCharCode(65+i)));const edges=[];for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){const dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y;edges.push({id:edges.length,a:nodes[i].id,b:nodes[j].id,w:Math.round(Math.hypot(dx,dy)*20)+1});}return{nodes,edges};}
