  function flowNetwork(withCosts=false){const nodes=[{id:'S',label:'S',x:.08,y:.5},{id:'A',label:'A',x:.3,y:.25},{id:'B',label:'B',x:.3,y:.72},{id:'C',label:'C',x:.58,y:.25},{id:'D',label:'D',x:.58,y:.72},{id:'T',label:'T',x:.88,y:.5}];const raw=withCosts?[['S','A',3,1],['S','B',3,2],['A','C',2,2],['A','D',2,3],['B','C',2,1],['B','D',3,1],['C','T',3,1],['D','T',3,2],['C','D',1,0]]:[['S','A',10,0],['S','B',8,0],['A','C',5,0],['A','D',5,0],['B','C',3,0],['B','D',7,0],['C','T',8,0],['D','T',9,0],['C','D',3,0]];return{nodes,edges:raw.map(([a,b,cap,cost],id)=>({id,a,b,cap,cost,flow:0,directed:true}))};}
