  function buildFft(){let values=nums($('input-a').value).slice(0,16);must(values.length>=2&&(values.length&(values.length-1))===0,'序列长度必须是 2 的幂');const n=values.length,bits=Math.log2(n),rev=(x)=>{let y=0;for(let i=0;i<bits;i++)y=y*2+((x>>i)&1);return y;};let a=values.map((v,i)=>({re:values[rev(i)],im:0})),ops=0;push('按位逆序重排输入','complex',{values:a.map(c=>c.re.toFixed(1)),stage:0,pairs:[]},[0,0,'--'],'BIT-REVERSAL PERMUTATION');for(let len=2,stage=1;len<=n;len*=2,stage++){const pairs=[];for(let i=0;i<n;i+=len)for(let j=0;j<len/2;j++){const angle=-2*Math.PI*j/len,w={re:Math.cos(angle),im:Math.sin(angle)},u=a[i+j],v=a[i+j+len/2],t={re:v.re*w.re-v.im*w.im,im:v.re*w.im+v.im*w.re};a[i+j]={re:u.re+t.re,im:u.im+t.im};a[i+j+len/2]={re:u.re-t.re,im:u.im-t.im};ops++;pairs.push([i+j,i+j+len/2]);push(`长度 ${len} 的蝶形 ${i+j} ↔ ${i+j+len/2}`,'complex',{values:a.map(c=>`${c.re.toFixed(1)}${c.im<0?'':'+'}${c.im.toFixed(1)}i`),stage,pairs:[pairs.at(-1)]},[stage,ops,'--'],'BUTTERFLY COMBINE');}}const mags=a.map(c=>Math.hypot(c.re,c.im)),peak=mags.indexOf(Math.max(...mags));push(`频率峰值位于 bin ${peak}`,'complex',{values:a.map(c=>`${c.re.toFixed(1)}${c.im<0?'':'+'}${c.im.toFixed(1)}i`),magnitudes:mags,stage:bits,pairs:[]},[bits,ops,peak],'FFT COMPLETE');}

