  function buildMillerRabin(){const n=Math.abs(Math.trunc(Number($('input-a').value)));must(Number.isSafeInteger(n)&&n>=2&&n<2147483648,'请输入 2 到 2³¹-1 的整数');if([2,3,5,7,11].includes(n)){push(`${n} 是质数`,'number',{title:'MILLER-RABIN',values:[{label:'N',value:n}],equation:'SMALL PRIME'},[n,0,'质数'],'DONE');return;}if(n%2===0){push(`${n} 是偶合数`,'number',{title:'MILLER-RABIN',values:[{label:'N',value:n},{label:'FACTOR',value:2}]},[2,0,'合数'],'EVEN COMPOSITE');return;}let d=n-1,s=0;while(d%2===0){d/=2;s++;}const bases=[2,3,5,7,11].filter(a=>a<n);let verdict='可能为质数';for(const a of bases){let x=Number(powMod(a,d,n)),witness=x!==1&&x!==n-1;push(`底数 ${a}：a^d mod n = ${x}`,'number',{title:'STRONG PROBABLE PRIME TEST',values:[{label:'BASE',value:a},{label:'D',value:d},{label:'X',value:x}],equation:`${n}-1 = ${d} × 2^${s}`},[a,0,'检查中'],'INITIAL POWER');for(let r=1;r<s&&witness;r++){x=Number(BigInt(x)*BigInt(x)%BigInt(n));push(`第 ${r} 次平方得到 ${x}`,'number',{title:'WITNESS LOOP',values:[{label:'BASE',value:a},{label:'ROUND',value:r},{label:'X',value:x}]},[a,r,'检查中'],'SQUARE MOD N');if(x===n-1)witness=false;}if(witness){verdict='合数';push(`${a} 是合数见证`,'number',{title:'COMPOSITE WITNESS',values:[{label:'N',value:n},{label:'WITNESS',value:a}]},[a,s,verdict],'COMPOSITE');break;}}if(verdict!=='合数')push(`${n} 通过确定性底数组测试`,'number',{title:'MILLER-RABIN RESULT',values:[{label:'N',value:n},{label:'BASES',value:bases.length}]},[bases.at(-1),s,verdict],'PRIME FOR 32-BIT RANGE');}

