  function buildCrt(){const rem=nums($('input-a').value).map(Math.round),mods=nums($('input-b').value).map(Math.round);must(rem.length&&rem.length===mods.length&&mods.every(m=>m>1),'余数与模数数量必须一致');const M=mods.reduce((a,b)=>a*b,1);let sum=0;for(let i=0;i<mods.length;i++){const Mi=M/mods[i],[g,x]=egcd(Mi,mods[i]);must(Math.abs(g)===1,'模数必须两两互质');const inv=(x%mods[i]+mods[i])%mods[i],term=rem[i]*Mi*inv;sum+=term;push(`合并 x ≡ ${rem[i]} (mod ${mods[i]})`,'number',{title:'CHINESE REMAINDER THEOREM',values:[{label:'Mᵢ',value:Mi},{label:'INVERSE',value:inv},{label:'PARTIAL',value:sum}],equation:`${rem[i]} × ${Mi} × ${inv}`},[i+1,sum,'--'],'ADD CONGRUENCE TERM');}const result=(sum%M+M)%M;push(`最小非负解为 ${result}`,'number',{title:'CRT RESULT',values:[{label:'X',value:result},{label:'MOD',value:M}],equation:`x ≡ ${result} (mod ${M})`},[mods.length,sum,result],'DONE');}

