  function buildLz77(){const text=$('input-a').value,windowSize=clamp(Math.round(Number($('input-b').value)||8),3,20);must(text.length,'请输入文本');let pos=0,tokens=[];while(pos<text.length){let bestLen=0,bestDist=0,start=Math.max(0,pos-windowSize);for(let j=start;j<pos;j++){let len=0;while(pos+len<text.length&&text[j+len]===text[pos+len]&&j+len<pos)len++;if(len>bestLen){bestLen=len;bestDist=pos-j;}}const next=text[pos+bestLen]??'∅';tokens.push(`(${bestDist},${bestLen},${next})`);push(bestLen?`找到长度 ${bestLen} 的窗口匹配`:`输出字面字符 ${next}`,'text',{rows:[{label:'INPUT',cells:[...text],active:[pos],range:[start,pos-1],selected:Array.from({length:bestLen},(_,i)=>pos+i)},{label:'TOKENS',cells:tokens}]},[pos,bestLen,tokens.length],bestLen?`DISTANCE ${bestDist}`:'LITERAL');pos+=bestLen+1;}}

  function buildLzw(){const text=$('input-a').value;must(text.length,'请输入文本');const alphabet=[...new Set([...text])].sort(),dict=new Map(alphabet.map((c,i)=>[c,i])),output=[];let w='',pos=0;for(const c of text){const wc=w+c;if(dict.has(wc))w=wc;else{output.push(dict.get(w));dict.set(wc,dict.size);push(`加入词典 ${wc} → ${dict.size-1}`,'dictionary',{entries:[...dict.entries()].slice(-18),output,active:wc,input:text,pos},[pos,dict.size,output.at(-1)],`EMIT ${w}`);w=c;}pos++;}if(w)output.push(dict.get(w));push('LZW 编码完成','dictionary',{entries:[...dict.entries()].slice(-18),output,input:text,pos:text.length},[text.length,dict.size,output.at(-1)],`CODES ${output.join(' ')}`);}

