  function buildDancingLinks(){const cols=['1','2','3','4','5','6','7'],rows=[['A',[1,4,7]],['B',[1,4]],['C',[4,5,7]],['D',[3,5,6]],['E',[2,3,6,7]],['F',[2,7]]],matrix=rows.map(([,set])=>cols.map(c=>set.includes(Number(c))?1:0)),activeCols=new Set(cols.map((_,i)=>i)),selected=[];function solve(depth){if(!activeCols.size)return true;let c=[...activeCols].sort((a,b)=>rows.filter(([,s])=>s.includes(a+1)&&s.every(x=>!activeCols.has(x-1)||true)).length-rows.filter(([,s])=>s.includes(b+1)).length)[0];const candidates=rows.map((r,i)=>[r,i]).filter(([[,set]])=>set.includes(c+1));for(const [[name,set],ri] of candidates){const conflicts=selected.some(si=>rows[si][1].some(x=>set.includes(x)));if(conflicts)continue;selected.push(ri);const removed=set.filter(x=>activeCols.has(x-1));removed.forEach(x=>activeCols.delete(x-1));push(`深度 ${depth} 选择行 ${name}`,'matrix',{matrix,active:[ri,c],selected:selected.flatMap(r=>rows[r][1].map(x=>[r,x-1])),rowLabels:rows.map(r=>r[0]),colLabels:cols,disabledCols:cols.map((_,i)=>!activeCols.has(i)?i:-1).filter(i=>i>=0)},[depth,activeCols.size,selected.length],`COVER ${removed.join(',')}`);if(solve(depth+1))return true;removed.forEach(x=>activeCols.add(x-1));selected.pop();push(`恢复行 ${name} 覆盖的列`,'matrix',{matrix,active:[ri,c],selected:selected.flatMap(r=>rows[r][1].map(x=>[r,x-1])),rowLabels:rows.map(r=>r[0]),colLabels:cols},[depth,activeCols.size,selected.length],'UNCOVER / BACKTRACK');}return false;}solve(1);push(`精确覆盖解：${selected.map(i=>rows[i][0]).join(', ')}`,'matrix',{matrix,selected:selected.flatMap(r=>rows[r][1].map(x=>[r,x-1])),rowLabels:rows.map(r=>r[0]),colLabels:cols},[selected.length,0,selected.length],'ALGORITHM X COMPLETE');}

