  function refreshPalette(){const style=getComputedStyle(document.body);palette=Object.fromEntries(['bg','panel','panel-2','text','muted','line','accent','accent-2','good','danger','ink'].map(name=>[name,style.getPropertyValue(`--${name}`).trim()]));}
  function clear(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=palette.bg;ctx.fillRect(0,0,width,height);ctx.strokeStyle=palette.line;ctx.lineWidth=1;for(let x=40;x<width;x+=80){ctx.beginPath();ctx.moveTo(x,100);ctx.lineTo(x,height-44);ctx.stroke();}for(let y=140;y<height;y+=80){ctx.beginPath();ctx.moveTo(18,y);ctx.lineTo(width-18,y);ctx.stroke();}}
  function label(text,x,y,color=palette.muted,align='left',font='11px ui-monospace, Consolas, monospace'){ctx.fillStyle=color;ctx.font=font;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(String(text),x,y);}
